let state;try{state=JSON.parse(localStorage.getItem('launchpad-v1'))||seed()}catch{state=seed()}
let page=location.hash.slice(1)||'journey',filters={query:'',level:'All levels',craft:'All crafts',team:'All teams',recommended:false};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),user=()=>hires.find(h=>h.id===state.selected),task=id=>tasks.find(t=>t.id===id),entries=(id=state.selected)=>state.entries.filter(e=>e.hire===id),approved=id=>entries(id).filter(e=>e.status==='approved'),entry=id=>entries().find(e=>e.task===id),save=()=>localStorage.setItem('launchpad-v1',JSON.stringify(state));
function progress(id=state.selected){const a=approved(id),counts={Basic:0,Intermediate:0,Expert:0};a.forEach(e=>counts[task(e.task).level]++);return{counts,graduated:counts.Basic>=3||counts.Intermediate>=2||counts.Expert>=1,points:a.reduce((s,e)=>s+task(e.task).points,0),ai:a.filter(e=>e.badge).length,pairs:a.filter(e=>e.partner).length}}
function score(t){let h=user(),n=0,reasons=[];if(t.craft===h.craft){n+=40;reasons.push('Matches your craft')}if(t.team===h.team){n+=25;reasons.push('Your hiring team')}let overlap=t.skills.filter(s=>h.skills.includes(s));if(overlap.length){n+=Math.min(25,overlap.length*15);reasons.push(overlap.join(' + '))}if(state.training[h.id].includes(t.prereq))n+=10;return{n,reasons}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function goto(p){location.hash=p;if(page===p)render()}
const buttons=[['journey','◈','My journey'],['marketplace','▦','Task marketplace'],['quests','⚑','My quests'],['cohort','◎','Cohort arena'],['review','✓','Review desk']];
function render(){if(!buttons.some(b=>b[0]===page))page='journey';$('#nav').innerHTML=buttons.map(([p,i,n])=>`<a href="#${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}><span>${i}</span>${n}${p==='review'&&state.entries.some(e=>e.status==='review')?' · '+state.entries.filter(e=>e.status==='review').length:''}</a>`).join('');$('#person').innerHTML=hires.map(h=>`<option value="${h.id}" ${h.id===state.selected?'selected':''}>${h.name}</option>`).join('');$('#avatar').textContent=user().initials;$('#app').innerHTML=({journey:journey,marketplace:marketplace,quests:quests,cohort:cohort,review:review})[page]();bind()}
function heading(k,h,p,side=''){return`<div class="topline"><div><div class="kicker">${k}</div><h1>${h}</h1><p class="subtitle">${p}</p></div>${side}</div>`}
function cards(list){return list.length?list.map(t=>{let s=score(t),e=entry(t.id);return`<article class="card"><div class="card-top"><span class="ticket">${t.id} · ${t.team}</span><span class="pill ${t.level}">${t.level}</span></div><h3>${t.title}</h3><p>${t.description}</p><div class="tags">${t.skills.map(s=>`<span class="tag">${s}</span>`).join('')}<span class="tag">${t.pair?'♧ Pair friendly':'Individual quest'}</span></div><div class="match">${s.reasons.length?'↗ '+s.reasons.join(' · '):'↗ Explore a new area'}</div><div class="card-bottom"><span>${t.points} pts · ${t.pair?'1–2 learners':'1 learner'}</span><button class="text-button" data-task="${t.id}">${e?({active:'Continue',review:'In review',approved:'Completed',changes:'Revise'})[e.status]:'View quest'} ↗</button></div></article>`}).join(''):'<div class="empty">No tasks match these filters. Try another skill or difficulty.</div>'}
function journey(){let h=user(),p=progress(),n=approved().length;return heading('YOUR FIRST THREE WEEKS',`A strong start, ${h.name.split(' ')[0]}.`,'Turn what you learn into something real. Your next contribution starts here.','<span class="pill">October 2026 · Demo cohort</span>')+`<section class="hero"><div class="hero-copy"><div class="kicker">LEARN. CONTRIBUTE. CONNECT.</div><h2>Your next chapter starts<br>with a real contribution.</h2><p>Discover meaningful product tasks, meet your cohort, and build confidence in your new team’s technology.</p><button class="btn" data-go="marketplace">Find your next quest ↗</button></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="rocket">↗</span></div><span class="star" style="top:30px;right:55px">✦</span><span class="star" style="bottom:40px;left:45px">✧</span></div></section><div class="stats"><div class="stat"><label>APPROVED CONTRIBUTIONS</label><strong>${n}<span class="muted" style="font-size:16px"> tasks</span></strong><small>Reviewed work that matters</small></div><div class="stat"><label>CONTRIBUTION POINTS</label><strong>${p.points}</strong><small>Earned through approved work</small></div><div class="stat"><label>AI PRACTICE VERIFIED</label><strong>${p.ai}</strong><small>Judgment + verification</small></div><div class="stat"><label>BOOT CAMP STATUS</label><strong style="font-size:22px">${p.graduated?'Graduated ✦':'In progress'}</strong><small>${h.role} · ${h.team}</small></div></div><div class="two-col"><section class="panel"><div class="kicker">YOUR GRADUATION PASSPORT</div><h2 style="margin-top:8px">Choose your path. Make it count.</h2><p class="note">Complete any one path with reviewer-approved contributions.</p>${[['Basic',3],['Intermediate',2],['Expert',1]].map(([l,total])=>`<div class="path"><div class="path-head"><strong>${l} path</strong><span>${p.counts[l]} / ${total} tasks</span></div><div class="progress"><div style="width:${Math.min(100,p.counts[l]/total*100)}%"></div></div></div>`).join('')}<p class="note">Mixed difficulties remain separate. Points do not replace graduation requirements.</p></section><section class="panel"><div class="kicker">FOUNDATIONS FIRST</div><h2 style="margin-top:8px">Your learning essentials</h2><p class="note">Sample learning journey for ${h.craft.toLowerCase()} engineering. Mark sessions attended to unlock prerequisites.</p>${training.map(t=>`<div class="training"><label><input type="checkbox" data-training="${t}" ${state.training[h.id].includes(t)?'checked':''}>${t}</label><span class="muted" style="font-size:10px">${state.training[h.id].includes(t)?'Complete':'Required'}</span></div>`).join('')}</section></div><div class="section-head"><div><h2>Picked for your next step</h2><p>Recommendations based on your craft, team, skills, and learning readiness.</p></div><button class="text-button" data-go="marketplace">Explore all quests ↗</button></div><div class="grid">${cards(tasks.filter(t=>!entry(t.id)).sort((a,b)=>score(b).n-score(a).n).slice(0,3))}</div><div class="week-strip"><div class="week current"><strong>01 · Find your footing</strong>Complete foundations and your first basic contribution.</div><div class="week"><strong>02 · Build with others</strong>Pair up, explore the stack, and tackle a new challenge.</div><div class="week"><strong>03 · Show what you learned</strong>Get work reviewed, share your learning, and graduate.</div></div>`}
function options(arr,v){return arr.map(a=>`<option ${a===v?'selected':''}>${a}</option>`).join('')}
function marketplace(){let list=tasks.filter(t=>(filters.level==='All levels'||t.level===filters.level)&&(filters.craft==='All crafts'||t.craft===filters.craft)&&(filters.team==='All teams'||t.team===filters.team)&&(!filters.recommended||t.craft===user().craft)&&[t.title,t.id,t.team,...t.skills].join(' ').toLowerCase().includes(filters.query.toLowerCase())).sort((a,b)=>score(b).n-score(a).n);return heading('FIND YOUR NEXT CONTRIBUTION','The task marketplace.','Real product problems. Bounded scope. A chance to grow.')+`<div class="filters"><input id="search" aria-label="Search tasks" placeholder="Search tasks, skills, or teams…" value="${esc(filters.query)}"><select id="difficulty" aria-label="Difficulty">${options(['All levels','Basic','Intermediate','Expert'],filters.level)}</select><select id="craft" aria-label="Craft">${options(['All crafts','Backend','Frontend','Platform','Quality'],filters.craft)}</select><select id="team" aria-label="Team">${options(['All teams',...new Set(tasks.map(t=>t.team))],filters.team)}</select><button class="btn ${filters.recommended?'':'secondary'}" id="recommended">${filters.recommended?'✓ ':''}My craft</button></div><p class="note">${list.length} quests · Sorted by match · Sample Jira backlog · Task owner reviews every contribution</p><div class="grid">${cards(list)}</div>`}
function quests(){let list=entries();return heading('YOUR CONTRIBUTIONS','From first step to shipped.','Your active quests, learning evidence, and approved contributions.')+(list.length?`<div class="grid">${cards(list.map(e=>task(e.task)))}</div><div class="section-head"><h2>Contribution status</h2></div><section class="panel">${list.map(e=>`<div class="training"><span>${task(e.task).title}${e.partner?`<br><small class="muted">Paired with ${hires.find(h=>h.id===e.partner).name}</small>`:''}</span><span class="pill status">${({active:'In progress',review:'Awaiting review',approved:'Approved',changes:'Changes requested'})[e.status]}</span></div>`).join('')}</section>`:'<div class="empty">Your first quest is waiting. <button class="text-button" data-go="marketplace">Explore the marketplace ↗</button></div>')}
function cohort(){let ranking=hires.map(h=>({...h,...progress(h.id),done:approved(h.id).length})).sort((a,b)=>b.points-a.points),total=state.entries.filter(e=>e.status==='approved').length,p=progress();return heading('GROW BETTER, TOGETHER','Your cohort. Your crew.','Celebrate contributions, learn from each other, and make progress together.')+`<section class="hero"><div class="hero-copy"><div class="kicker">OUR SHARED OCTOBER MISSION</div><h2>20 reviewed contributions.<br>One stronger cohort.</h2><p>Every approved individual contribution brings the crew closer. Pair work counts once per reviewed participant.</p><div class="progress"><div style="width:${Math.min(100,total/20*100)}%"></div></div><small>${total} / 20 approved contributions</small></div><div class="hero-art"><span class="rocket">✦</span></div></section><div class="two-col"><section class="panel"><h2>Contribution leaderboard</h2><p class="note">Basic: 100 pts · Intermediate: 175 pts · Expert: 300 pts<br>AI usage volume earns no extra points.</p><div class="table-wrap"><table><thead><tr><th>Rank / learner</th><th>Tasks</th><th>Points</th><th>AI badges</th></tr></thead><tbody>${ranking.map((h,i)=>`<tr class="${h.id===state.selected?'me':''}"><td><div class="person-cell"><span class="muted">${i+1}</span><span class="avatar">${h.initials}</span><span>${h.name}${h.id===state.selected?' · You':''}<br><small class="muted">${h.craft}</small></span></div></td><td>${h.done}</td><td><strong>${h.points}</strong></td><td>${h.ai}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Your achievements</h2><p class="note">Milestones that recognize learning and contribution.</p><div class="badge-grid">${[['✧','First contribution','Your first approved task',approved().length>0],['✦','AI practice verified','AI judgment confirmed by a reviewer',p.ai>0],['♧','Better together','An approved pair contribution',p.pairs>0],['↗','Stack explorer','Approved work outside your craft',approved().some(e=>task(e.task).craft!==user().craft)],['⚑','Boot camp graduate','Complete a graduation path',p.graduated],['◎','Keep growing','Approved work beyond a graduation threshold',p.counts.Basic>3||p.counts.Intermediate>2||p.counts.Expert>1]].map(([s,n,d,on])=>`<div class="badge ${on?'':'locked'}"><span class="symbol">${s}</span><strong>${n}</strong><p>${d}</p><small>${on?'Unlocked':'Not yet unlocked'}</small></div>`).join('')}</div></section></div>`}
function review(){let list=state.entries.filter(e=>e.status==='review');return heading('PROGRAM MANAGER · DEMO VIEW','Recognize the work. Verify the learning.','Review each learner’s contribution before awarding graduation credit.')+`<div class="callout">Prototype role switch: this review desk is available to everyone for demonstration. Production needs authenticated reviewer permissions and independently verified work evidence.</div><section class="panel"><h2>${list.length} contribution${list.length===1?'':'s'} awaiting review</h2>${list.length?list.map(e=>{let t=task(e.task),h=hires.find(h=>h.id===e.hire);return`<article class="review"><div class="card-top"><span class="kicker">${h.name} · ${t.id}</span><span class="pill ${t.level}">${t.level}</span></div><h3>${t.title}</h3><p><strong>Evidence:</strong> ${esc(e.evidence)}${e.partner?'<br><strong>Partner:</strong> '+hires.find(h=>h.id===e.partner).name:''}</p><blockquote><strong>AI usage:</strong> ${e.ai==='yes'?'Used AI':'No AI used'}<br><strong>Approach:</strong> ${esc(e.use)}<br><strong>Judgment:</strong> ${esc(e.judgment)}<br><strong>Verification:</strong> ${esc(e.verify)}<br><strong>Learning:</strong> ${esc(e.learn)}</blockquote><label class="note"><input type="checkbox" id="verify-${e.hire}-${e.task}"> I reviewed the evidence and confirmed this learner’s contribution meets acceptance criteria.</label>${e.ai==='yes'?`<p><label class="note"><input type="checkbox" id="badge-${e.hire}-${e.task}"> Also verify AI judgment and understanding (awards AI Practice badge).</label></p>`:''}<label class="field">Feedback for learner<textarea id="feedback-${e.hire}-${e.task}" placeholder="Required when requesting changes"></textarea></label><div class="actions"><button class="btn" data-approve="${e.hire}|${e.task}">Approve contribution · ${t.points} pts</button><button class="btn secondary" data-changes="${e.hire}|${e.task}">Request changes</button></div></article>`}).join(''):'<div class="empty">All caught up. New submissions will appear here.</div>'}</section>`}
function openTask(id){let t=task(id),e=entry(id),h=user(),ready=state.training[h.id].includes(t.prereq),members=state.entries.filter(x=>x.task===id),s=score(t);$('#modal').innerHTML=`<button class="close" aria-label="Close dialog">×</button><span class="ticket">${t.id} · ${t.team} · Owner: ${t.owner}</span><h2>${t.title}</h2><span class="pill ${t.level}">${t.level}</span> <span class="pill">${t.points} points after approval</span><p>${t.description}</p><div class="callout"><strong>Why this quest?</strong> ${s.reasons.join(' · ')||'An opportunity to explore a new area.'}<br><strong>Prerequisite:</strong> ${t.prereq} ${ready?'✓ Complete':'· Complete in My journey before starting'}</div><h3>Acceptance criteria</h3><ul><li>Agree on scope with ${t.owner} before making changes.</li><li>Deliver the described change with appropriate tests or reproducible evidence.</li><li>Explain your contribution and have the owner review the result.</li></ul><h3>AI practice opportunity</h3><p>Use an approved AI tool to explore the code, propose edge cases, or review an approach. Assess its suggestions and verify the result. Record your judgment; using AI is optional.</p>${members.length?'<p><strong>Participants:</strong> '+members.map(x=>hires.find(h=>h.id===x.hire).name).join(', ')+'</p>':''}${e?`<div class="callout">Status: ${esc(e.status)}${e.partner?' · Partner: '+hires.find(h=>h.id===e.partner).name:''}${e.feedback?'<br>Reviewer feedback: '+esc(e.feedback):''}</div>${['active','changes'].includes(e.status)?submissionForm(e):'<p class="note">'+(e.status==='approved'?'Your contribution has been approved. Credit is already reflected in your passport.':'Your contribution is waiting for individual review.')+'</p>'}`:members.length>=(t.pair?2:1)?'<div class="callout">This quest is full. Choose another quest.</div>':!ready?'<button class="btn" id="training-link">Complete prerequisite →</button>':`<p class="note">${t.pair?'Pair friendly: invite one cohort member or join the existing participant. Each person submits their own evidence.':'This quest is designed for an individual contributor.'}</p>${t.pair&&members.length===0?`<label class="field">Optional: choose a partner<select id="partner"><option value="">Work individually for now</option>${hires.filter(x=>x.id!==h.id&&state.training[x.id].includes(t.prereq)).map(x=>`<option value="${x.id}">${x.name} · ${x.craft}</option>`).join('')}</select></label>`:''}<button class="btn" id="claim">${members.length?'Join pair quest':'Start this quest'} ↗</button>`}`;$('#modal').showModal();$('.close').onclick=()=>$('#modal').close();if($('#claim'))$('#claim').onclick=()=>{let partner=$('#partner')?.value||members[0]?.hire;state.entries.push({task:id,hire:h.id,status:'active',partner});if(partner){let other=state.entries.find(x=>x.task===id&&x.hire===partner);if(other)other.partner=h.id;else state.entries.push({task:id,hire:partner,status:'active',partner:h.id})}save();$('#modal').close();render();toast('Quest started. Your contribution journey begins.')};if($('#training-link'))$('#training-link').onclick=()=>{$('#modal').close();goto('journey')};if($('#submission'))$('#submission').onsubmit=ev=>{ev.preventDefault();let data=new FormData(ev.target);Object.assign(e,Object.fromEntries(data),{status:'review',badge:false});save();$('#modal').close();render();toast('Submitted for review. Points follow reviewer approval.')}}
function submissionForm(e){return`<form id="submission"><h3>Your work & learning evidence</h3><label class="field">Work evidence or pull request reference<input name="evidence" required value="${esc(e.evidence||'')}" placeholder="Describe or reference the work you completed"></label><label class="field">Did you use AI?<select name="ai"><option value="yes" ${e.ai==='yes'?'selected':''}>Yes — record how you used and checked it</option><option value="no" ${e.ai==='no'?'selected':''}>No — describe your approach</option></select></label>${[['use','What did AI help with, or what approach did you use?'],['judgment','What did you accept, change, or reject—and why?'],['verify','How did you verify the completed work?'],['learn','What can you now explain independently?']].map(([n,l])=>`<label class="field">${l}<textarea name="${n}" required>${esc(e[n]||'')}</textarea></label>`).join('')}<p class="note">Record your own contribution for shared tasks. Use fictional evidence for this demo.</p><button class="btn" type="submit">Submit for review ↗</button></form>`}
function bind(){$$('[data-go]').forEach(b=>b.onclick=()=>goto(b.dataset.go));$$('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.task));$$('[data-training]').forEach(b=>b.onchange=()=>{let a=state.training[state.selected];state.training[state.selected]=b.checked?[...a,b.dataset.training]:a.filter(x=>x!==b.dataset.training);save();render()});if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;filters.query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};[['difficulty','level'],['craft','craft'],['team','team']].forEach(([id,key])=>{if($('#'+id))$('#'+id).onchange=e=>{filters[key]=e.target.value;render()}});if($('#recommended'))$('#recommended').onclick=()=>{filters.recommended=!filters.recommended;render()};$$('[data-approve]').forEach(b=>b.onclick=()=>{let [h,t]=b.dataset.approve.split('|');if(!$('#verify-'+h+'-'+t).checked)return toast('Confirm that you reviewed the contribution first.');let e=state.entries.find(e=>e.hire===h&&e.task===t);e.status='approved';e.badge=!!$('#badge-'+h+'-'+t)?.checked;e.feedback=$('#feedback-'+h+'-'+t).value;save();render();toast('Contribution approved. Points and graduation progress updated.')});$$('[data-changes]').forEach(b=>b.onclick=()=>{let[h,t]=b.dataset.changes.split('|'),feedback=$('#feedback-'+h+'-'+t).value.trim();if(!feedback)return toast('Add feedback so the learner knows what to improve.');let e=state.entries.find(e=>e.hire===h&&e.task===t);e.status='changes';e.feedback=feedback;save();render();toast('Changes requested. Learner can revise and resubmit.')})}
function $$(s){return[...document.querySelectorAll(s)]}
$('#person').onchange=e=>{state.selected=e.target.value;save();render()};$('#reset').onclick=()=>{if(confirm('Reset all demo progress to the sample starting data?')){state=seed();save();render();toast('Demo reset.')}};window.onhashchange=()=>{page=location.hash.slice(1)||'journey';render()};render();
